mapper.select:
select #{TRADE_FLOW_STATUS_01} as activeState, wtfpdt.TOTLE_TRADE_ID as totleTradeId, wtfpdt.PS as ps, DATE_FORMAT(wtfpdt.TRADE_DATE, '%Y-%m-%d') as tradeDate, wtfpdt.SHARE_AMT as shareAmt, wtfpdt.FPRICE_AMT as fpriceAmt, bb.BOOKSET_ID as booksetId, bb.BOOKSET_NAME as booksetName, fri.BENCHMARK_ID as benchmarkId, DATE_FORMAT(spo.SETTLE_DATE, '%Y-%m-%d') as settleDate, fris.EXE_PRICE as exePrice, ftra.OPT_FEE_PAY_TYPE as optFeePayType from WFL_TRD_FIN_PRODUCT_DEAL_TOTAL wtfpdt left join PTL_TRADE pt on pt.PORTFOLIO_ID = wtfpdt.PORTFOLIO_ID left join BOK_DEAL_ACCOUNTING bda on bda.BUSI_NO = pt.BUSI_NO left join BOK_BOOKSET bb on bb.BOOKSET_ID = bda.BOOKSET_ID left join FIN_RATE_INFO fri on fri.FINPROD_ID = wtfpdt.FINPROD_ID left join STL_PAY_ORDERS spo on spo.TRADE_ID = wtfpdt.TOTLE_TRADE_ID left join FIN_RATE_INFO_STRUCTURE fris on fris.CASH_ID = wtfpdt.CASH_ID left join FIN_TRADE_PRODUCT_ADD ftra on ftra.FINPROD_ID = wtfpdt.FINPROD_ID where wtfpdt.IS_CANCEL != #{YES_OR_NO_Y} and wtfpdt.TRADE_STATUS = #{TRADE_STATUS_01} and wtfpdt.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F35}
AND bb.BOOKSET_ID = #{booksetId}
AND wtfpdt.TOTLE_TRADE_ID = #{totleTradeId}
AND fri.BENCHMARK_ID = #{benchmarkId}
AND wtfpdt.PS = #{ps}
AND ftra.OPT_FEE_PAY_TYPE = #{optFeePayType}
AND activeState = #{activeState}
AND wtfpdt.TRADE_DATE >=STR_TO_DATE(#{tradeDateStart},'%Y-%m-%d')
AND wtfpdt.TRADE_DATE <=STR_TO_DATE(#{tradeDateEnd},'%Y-%m-%d')
union select #{TRADE_FLOW_STATUS_02} as activeState, tfpdt.TOTLE_TRADE_ID as totleTradeId, tfpdt.PS as ps, DATE_FORMAT(tfpdt.TRADE_DATE, '%Y-%m-%d') as tradeDate, tfpdt.SHARE_AMT as shareAmt, tfpdt.FPRICE_AMT as fpriceAmt, bb.BOOKSET_ID as booksetId, bb.BOOKSET_NAME as booksetName, fri.BENCHMARK_ID as benchmarkId, DATE_FORMAT(spo.SETTLE_DATE, '%Y-%m-%d') as settleDate, fris.EXE_PRICE as exePrice, ftra.OPT_FEE_PAY_TYPE as optFeePayType from TRD_FIN_PRODUCT_DEAL_TOTAL tfpdt left join PTL_TRADE pt on pt.PORTFOLIO_ID = tfpdt.PORTFOLIO_ID left join BOK_DEAL_ACCOUNTING bda on bda.BUSI_NO = pt.BUSI_NO left join BOK_BOOKSET bb on bb.BOOKSET_ID = bda.BOOKSET_ID left join FIN_RATE_INFO fri on fri.FINPROD_ID = tfpdt.FINPROD_ID left join STL_PAY_ORDERS spo on spo.TRADE_ID = tfpdt.TOTLE_TRADE_ID left join FIN_RATE_INFO_STRUCTURE fris on fris.CASH_ID = tfpdt.CASH_ID left join FIN_TRADE_PRODUCT_ADD ftra on ftra.FINPROD_ID = tfpdt.FINPROD_ID where tfpdt.IS_CANCEL != #{YES_OR_NO_Y} and tfpdt.TRADE_STATUS = #{TRADE_STATUS_01} and tfpdt.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F35}
AND bb.BOOKSET_ID = #{booksetId}
AND tfpdt.TOTLE_TRADE_ID = #{totleTradeId}
AND fri.BENCHMARK_ID = #{benchmarkId}
AND tfpdt.PS = #{ps}
AND ftra.OPT_FEE_PAY_TYPE = #{optFeePayType}
AND activeState = #{activeState}
AND tfpdt.TRADE_DATE >=STR_TO_DATE(#{tradeDateStart},'%Y-%m-%d')
AND tfpdt.TRADE_DATE <=STR_TO_DATE(#{tradeDateEnd},'%Y-%m-%d')
union select #{TRADE_FLOW_STATUS_03} as activeState, tfpdt.TOTLE_TRADE_ID as totleTradeId, tfpdt.PS as ps, DATE_FORMAT(tfpdt.TRADE_DATE, '%Y-%m-%d') as tradeDate, tfpdt.SHARE_AMT as shareAmt, tfpdt.FPRICE_AMT as fpriceAmt, bb.BOOKSET_ID as booksetId, bb.BOOKSET_NAME as booksetName, fri.BENCHMARK_ID as benchmarkId, DATE_FORMAT(spo.SETTLE_DATE, '%Y-%m-%d') as settleDate, fris.EXE_PRICE as exePrice, ftra.OPT_FEE_PAY_TYPE as optFeePayType from TRD_FIN_PRODUCT_DEAL_TOTAL tfpdt left join PTL_TRADE pt on pt.PORTFOLIO_ID = tfpdt.PORTFOLIO_ID left join BOK_DEAL_ACCOUNTING bda on bda.BUSI_NO = pt.BUSI_NO left join BOK_BOOKSET bb on bb.BOOKSET_ID = bda.BOOKSET_ID left join FIN_RATE_INFO fri on fri.FINPROD_ID = tfpdt.FINPROD_ID left join STL_PAY_ORDERS spo on spo.TRADE_ID = tfpdt.TOTLE_TRADE_ID left join FIN_RATE_INFO_STRUCTURE fris on fris.CASH_ID = tfpdt.CASH_ID left join FIN_TRADE_PRODUCT_ADD ftra on ftra.FINPROD_ID = tfpdt.FINPROD_ID where tfpdt.IS_CANCEL = #{YES_OR_NO_Y} and tfpdt.TRADE_STATUS = #{TRADE_STATUS_01} and tfpdt.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F35}
AND bb.BOOKSET_ID = #{booksetId}
AND tfpdt.TOTLE_TRADE_ID = #{totleTradeId}
AND fri.BENCHMARK_ID = #{benchmarkId}
AND tfpdt.PS = #{ps}
AND ftra.OPT_FEE_PAY_TYPE = #{optFeePayType}
AND activeState = #{activeState}
AND tfpdt.TRADE_DATE >=STR_TO_DATE(#{tradeDateStart},'%Y-%m-%d')
AND tfpdt.TRADE_DATE <=STR_TO_DATE(#{tradeDateEnd},'%Y-%m-%d')
